5|
6|/***
7| * MARK: AliasCollapsedRow
8| * @description The whole collapsed alias row as a pure presentational
9| *   component (state and handlers stay in `ModelAliasesSection`, passed down
10| *   via props). Two-line layout so long provider-prefixed model refs stay
11| *   readable instead of being ellipsized mid-name: line 1 is the header
12| *   (toggle + alias name + reliability line, delete on the right); line 2 is
13| *   a full-width wrapping row of per-target chips (`AliasTargetChip`), which
14| *   on narrow screens naturally becomes its own full-width line under the
15| *   alias name. A validation error renders on its own full-width line between
16| *   the two (never squeezed into the header), keeping its `role="alert"`
17| *   wrapper, badge test ids, and click-to-expand behaviour. All historic test
18| *   ids survive: `model-alias-toggle-{i}`, `model-alias-header-{i}`,
19| *   `model-alias-summary-{i}` (now the chips container), `model-alias-error-alert-{i}`
20| *   / `model-alias-error-badge-{i}`. Fails safe: a non-array `targets` renders
21| *   an empty "0 targets" chips line, and a blank alias name falls back to
22| *   `Alias {index+1}` — neither can crash the row.
23| * @example <AliasCollapsedRow index={0} aliasName="router" targets={targets} targetHarnesses={harnesses}
24| *   rowError="" disabled={false} onToggle={() => toggle(key)} onDelete={() => deleteRow(0)} reliabilityLine={node} />
25| *   => header line "▸ router … ✕" plus a wrapping chips line "50% Muse [google] gemini-3-pro …"
26| * @param {Object} props
27| * @param {number} props.index - Positional alias index (test ids + header id).
28| * @param {string} props.aliasName - Draft alias name (header text + accessible labels).
29| * @param {Array<Object>} props.targets - Target sub-rows for this alias (raw draft rows).
30| * @param {Array<Object>} [props.targetHarnesses=[]] - Catalogue harness view for labels/modelSelection.
31| * @param {string} [props.rowError=''] - Validation message for this row; renders on its own line when non-empty.
32| * @param {boolean} [props.disabled=false] - Disables toggle and delete.
33| * @param {Function} props.onToggle - Expand/collapse handler (also the error badge's click-to-expand).
34| * @param {Function} props.onDelete - Delete handler.
35| * @param {ReactNode} [props.reliabilityLine] - Rendered reliability line for the header (optional).
36| ***/
37|export function AliasCollapsedRow({
38|  index,
39|  aliasName,
40|  targets,
41|  targetHarnesses = [],
42|  rowError = '',
43|  disabled = false,
44|  onToggle,
45|  onDelete,
46|  reliabilityLine,
47|}) {
48|  const list = Array.isArray(targets) ? targets : [];
49|  const headerText = aliasName || `Alias ${index + 1}`;
50|  return (
51|    <div className="flex flex-col gap-1.5 min-w-0">
52|      <div className="flex items-center justify-between gap-2 flex-wrap min-w-0">
53|        <div className="flex items-center gap-2 min-w-0 flex-wrap">
54|          <CollapseToggleButton
55|            index={index}
56|            aliasName={aliasName}
57|            expanded={false}
58|            onToggle={onToggle}
59|            disabled={disabled}
60|          />
61|          <span
62|            id={`model-alias-header-${index}`}
63|            className="text-xs font-mono font-bold text-on-surface truncate"
64|            title={headerText}
65|          >
66|            {headerText}
67|          </span>
68|          {reliabilityLine}
69|        </div>
70|        <DeleteAliasButton
71|          index={index}
72|          aliasName={aliasName}
73|          onDelete={onDelete}
74|          disabled={disabled}
75|        />
76|      </div>
77|      {rowError && (
78|        <span
79|          role="alert"
80|          data-testid={`model-alias-error-alert-${index}`}
81|          className="block w-full min-w-0"
82|        >
83|          {/* Read-only view change: intentionally not disabled — expanding a
84|              card to read its error mutates nothing, even while saving. */}
85|          <button
86|            type="button"
87|            data-testid={`model-alias-error-badge-${index}`}
88|            onClick={onToggle}
89|            title={`${rowError} (Click to expand)`}
90|            className="px-1.5 py-0.5 bg-error/10 border border-error/50 rounded-sm text-[10px] font-bold text-error cursor-pointer break-all text-left"
91|          >
92|            ⚠ {rowError}
93|          </button>
94|        </span>
95|      )}
96|      <div
97|        data-testid={`model-alias-summary-${index}`}
98|        className="flex flex-wrap items-baseline gap-1.5 w-full min-w-0"
99|      >
100|        <span
101|          data-testid={`model-alias-summary-count-${index}`}
102|          className="text-[10px] text-text-muted whitespace-nowrap"
103|        >
104|          {list.length === 1 ? '1 target' : `${list.length} targets`}
105|        </span>
106|        {list.map((target, targetIndex) => (
107|          <AliasTargetChip
108|            key={targetIndex}
109|            testId={`model-alias-summary-chip-${index}-${targetIndex}`}
110|            summary={aliasTargetSummary(target, targetHarnesses)}
111|          />
112|        ))}
113|      </div>
114|    </div>
115|  );
116|}
117|
