1|import { parseModelKey, splitReasoning } from '../../services/modelKeys';
2|
3|/***
4| * MARK: splitModelRefProvider
5| * @description Splits a stored model reference into the provider badge and the
6| *   bare model id shown in the collapsed alias summary chips. An optional
7| *   `::reasoning` level is stripped first (via the shared `splitReasoning`
8| *   grammar), then the base ref is parsed with the shared `parseModelKey`:
9| *   canonical `harness::provider::id` yields `{ provider, modelId: id }` (the
10| *   harness half is already shown by the chip's harness label, so it is not
11| *   repeated), legacy `provider::id` yields `{ provider, modelId: id }`, and a
12| *   bare id yields `{ provider: '', modelId: id }` (no badge renders). Malformed
13| *   or blank input fails safe to `{ provider: '', modelId: <raw base> }` —
14| *   never throws, so a garbage stored ref still renders verbatim.
15| * @example splitModelRefProvider('google::gemini-3-pro') => { provider: 'google', modelId: 'gemini-3-pro' }
16| * @example splitModelRefProvider('pi::google::gemini-3-pro') => { provider: 'google', modelId: 'gemini-3-pro' }
17| * @example splitModelRefProvider('pi::google::gemini-3-pro::high') => { provider: 'google', modelId: 'gemini-3-pro' }
18| * @example splitModelRefProvider('gemini-3-pro') => { provider: '', modelId: 'gemini-3-pro' }
19| * @example splitModelRefProvider('') => { provider: '', modelId: '' }
20| * @param {string} ref - Stored model reference (any grammar form).
21| * @returns {{provider: string, modelId: string}} Provider badge text ('' when none) and the bare model id.
22| ***/
23|export function splitModelRefProvider(ref) {
24|  const baseRef = splitReasoning(typeof ref === 'string' ? ref : '').baseRef;
25|  const parsed = parseModelKey(baseRef);
26|  if (parsed && (parsed.form === 'harness' || parsed.form === 'provider')) {
27|    return { provider: parsed.provider, modelId: parsed.id };
28|  }
29|  if (parsed && parsed.form === 'bare') {
30|    return { provider: '', modelId: parsed.id };
31|  }
32|  // Malformed (5+ segments, empty segment) or blank: show the raw base
33|  // verbatim with no provider badge rather than dropping or mangling it.
34|  return { provider: '', modelId: baseRef };
35|}

