1|import { splitReasoning } from '../../services/modelKeys';
2|import { splitModelRefProvider } from './splitModelRefProvider';
3|
4|/***
5| * MARK: aliasTargetSummary
6| * @description Builds the structured summary of ONE alias target for the
7| *   collapsed row's target chips — the single source both the chip renderer
8| *   (`AliasTargetChip`) and the plain-text fallback (`formatAliasSummary`)
9| *   are built on, so the two can never drift apart. Mirrors the historic
10| *   `formatAliasSummary` semantics exactly: the harness label falls back to
11| *   the raw harness id, then to `unassigned`; the percent renders as `N%`
12| *   only when it is a real number; and the model ref is only "shown" when the
13| *   harness is list-based (`modelSelection !== 'none'`) and the stored model
14| *   is non-blank (a self-managed `none` harness ignores its stored model).
15| *   The model ref is additionally split into `provider` badge + `modelId`
16| *   (and carries the optional `reasoning` level) so the chip can render the
17| *   provider as a separate badge while the complete stored ref stays intact
18| *   in `modelRef`. Never throws on malformed input (blank/unassigned/`none`
19| *   rows all produce a renderable summary).
20| * @example aliasTargetSummary({ harness: 'pi', model: 'google::m1', percent: 100 }, [{ id: 'pi', label: 'pi', modelSelection: 'list' }])
21| *   => { percent: 100, percentText: '100%', harnessId: 'pi', harnessLabel: 'pi', modelRef: 'google::m1', showModel: true, provider: 'google', modelId: 'm1', reasoning: null }
22| * @example aliasTargetSummary({ harness: 'custom', model: 'ignored', percent: 50 }, [{ id: 'custom', label: 'Custom', modelSelection: 'none' }])
23| *   => { percent: 50, percentText: '50%', harnessId: 'custom', harnessLabel: 'Custom', modelRef: 'ignored', showModel: false, provider: '', modelId: 'ignored', reasoning: null }
24| * @example aliasTargetSummary({}, []) => { percent: null, percentText: '', harnessId: '', harnessLabel: 'unassigned', modelRef: '', showModel: false, provider: '', modelId: '', reasoning: null }
25| * @param {Object} target - One target sub-row (`{ harness, model, percent }`); may be blank or malformed.
26| * @param {Array<Object>} [targetHarnesses=[]] - Catalogue harness view (labels + modelSelection).
27| * @returns {{percent: number|null, percentText: string, harnessId: string, harnessLabel: string, modelRef: string, showModel: boolean, provider: string, modelId: string, reasoning: string|null}} Structured chip summary.
28| ***/
29|export function aliasTargetSummary(target, targetHarnesses = []) {
30|  const harnessId = typeof target?.harness === 'string' ? target.harness.trim() : '';
31|  const catalogue = Array.isArray(targetHarnesses) ? targetHarnesses : [];
32|  const entry = catalogue.find((h) => h?.id === harnessId);
33|  const harnessLabel = entry?.label || harnessId || 'unassigned';
34|  const rawPercent = target?.percent;
35|  const percent =
36|    typeof rawPercent === 'number' && !Number.isNaN(rawPercent) ? rawPercent : null;
37|  const percentText = percent === null ? '' : `${percent}%`;
38|  const modelRef = typeof target?.model === 'string' ? target.model.trim() : '';
39|  const showModel = entry?.modelSelection !== 'none' && modelRef !== '';
40|  const { provider, modelId } = splitModelRefProvider(modelRef);
41|  const { reasoning } = splitReasoning(modelRef);
42|  return {
43|    percent,
44|    percentText,
45|    harnessId,
46|    harnessLabel,
47|    modelRef,
48|    showModel,
49|    provider,
50|    modelId,
51|    reasoning,
52|  };
53|}

